func (d AccountDraft) foundryMutation(create bool) (foundryquery.Mutation[Account], error) {
	if create && !d.fieldID.IsSet() {
		id, err := model.NewID[Account]()
		if err != nil {
			return foundryquery.Mutation[Account]{}, err
		}
		d = d.SetID(id)
	}
	var assignments []foundryquery.Assignment[Account]
	if v, set := d.fieldID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Account]("mfa_accounts", "id", codec.ID[Account](), v))
	}
	if v, set := d.fieldEmail.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Account]("mfa_accounts", "email", codec.String[string](), v))
	}
	if v, set := d.fieldPassword.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Account]("mfa_accounts", "password", password.Codec(), v))
	}
	if v, set := d.fieldEnabled.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Account]("mfa_accounts", "enabled", codec.Bool[bool](), v))
	}
	if v, set := d.fieldMFAEnabled.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Account]("mfa_accounts", "mfa_enabled", codec.Bool[bool](), v))
	}
	if v, set := d.fieldRequireMFA.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Account]("mfa_accounts", "require_mfa", codec.Bool[bool](), v))
	}
	return foundryquery.Change(assignments...), nil
}

