// CompareAccount is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareAccount(before, after foundryvalue.Optional[Account], assigned AccountDraft) (AccountChanges, error) {
	before = foundryAccountSnapshot(before)
	after = foundryAccountSnapshot(after)
	var changes AccountChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Account](), before, after, assigned.fieldID.IsSet(), func(item Account) model.ID[Account] { return item.ID })
	if err != nil {
		return AccountChanges{}, fmt.Errorf("compare Account.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return AccountChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.Email, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldEmail.IsSet(), func(item Account) string { return item.Email })
	if err != nil {
		return AccountChanges{}, fmt.Errorf("compare Account.Email: %w", err)
	}
	changes.fields.Password, err = lifecycle.CompareModelField(password.Codec(), before, after, assigned.fieldPassword.IsSet(), func(item Account) password.Hash { return item.Password })
	if err != nil {
		return AccountChanges{}, fmt.Errorf("compare Account.Password: %w", err)
	}
	changes.fields.Enabled, err = lifecycle.CompareModelField(codec.Bool[bool](), before, after, assigned.fieldEnabled.IsSet(), func(item Account) bool { return item.Enabled })
	if err != nil {
		return AccountChanges{}, fmt.Errorf("compare Account.Enabled: %w", err)
	}
	changes.fields.MFAEnabled, err = lifecycle.CompareModelField(codec.Bool[bool](), before, after, assigned.fieldMFAEnabled.IsSet(), func(item Account) bool { return item.MFAEnabled })
	if err != nil {
		return AccountChanges{}, fmt.Errorf("compare Account.MFAEnabled: %w", err)
	}
	changes.fields.RequireMFA, err = lifecycle.CompareModelField(codec.Bool[bool](), before, after, assigned.fieldRequireMFA.IsSet(), func(item Account) bool { return item.RequireMFA })
	if err != nil {
		return AccountChanges{}, fmt.Errorf("compare Account.RequireMFA: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundryAccountSnapshot(snapshot foundryvalue.Optional[Account]) foundryvalue.Optional[Account] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Account]{}
	}
	return foundryvalue.Set(Account{
		ID:         item.ID,
		Email:      item.Email,
		Password:   item.Password,
		Enabled:    item.Enabled,
		MFAEnabled: item.MFAEnabled,
		RequireMFA: item.RequireMFA,
	})
}

// AccountHooks declares typed normal-write callbacks. Reference a factory with hooks=Factory on the model directive. Callbacks run synchronously; do not retain draft or transaction pointers. Nil callbacks are skipped.
type AccountHooks struct {
	// Saving runs before Creating or Updating and may change assigned fields.
	Saving func(context.Context, *database.Tx, foundryvalue.Optional[Account], *AccountDraft) error
	// Creating runs before insert mutators; omitted required fields may be supplied here.
	Creating func(context.Context, *database.Tx, *AccountDraft) error
	// Updating receives the locked stored model before the write.
	Updating func(context.Context, *database.Tx, Account, *AccountDraft) error
	// Deleting receives the locked stored model before soft or physical deletion.
	Deleting func(context.Context, *database.Tx, Account) error
	// Restoring receives the locked stored model before its special lifecycle write.
	Restoring func(context.Context, *database.Tx, Account) error
	// ForceDeleting receives the locked stored model before its special lifecycle write.
	ForceDeleting func(context.Context, *database.Tx, Account) error
	// Created runs after SQL inside the transaction; returning an error rolls back the write.
	Created func(context.Context, *database.Tx, AccountChanges) error
	// Updated runs after SQL inside the transaction; returning an error rolls back the write.
	Updated func(context.Context, *database.Tx, AccountChanges) error
	// Deleted runs after SQL inside the transaction; returning an error rolls back the write.
	Deleted func(context.Context, *database.Tx, AccountChanges) error
	// Saved runs after SQL inside the transaction; returning an error rolls back the write.
	Saved func(context.Context, *database.Tx, AccountChanges) error
	// Restored runs after SQL inside the transaction; returning an error rolls back the write.
	Restored func(context.Context, *database.Tx, AccountChanges) error
	// ForceDeleted runs after SQL inside the transaction; returning an error rolls back the write.
	ForceDeleted func(context.Context, *database.Tx, AccountChanges) error
	// AfterCommit runs only after the outer transaction commits. Failures cannot roll back committed data; this callback is not crash durable.
	AfterCommit func(context.Context, lifecycle.Operation, AccountChanges) error
}

