// AccountAuditPolicy selects stored fields for auditing. Zero applies automatic sensitive-name redaction.
// Exclusion/redaction cannot hide the primary key while retaining it as the subject identity; that policy fails capture.
type AccountAuditPolicy struct {
	_ [0]*Account
	// ID controls the audit representation of stored mfa_accounts.id.
	ID record.Disclosure
	// Email controls the audit representation of stored mfa_accounts.email.
	Email record.Disclosure
	// Password controls the audit representation of stored mfa_accounts.password.
	Password record.Disclosure
	// Enabled controls the audit representation of stored mfa_accounts.enabled.
	Enabled record.Disclosure
	// MFAEnabled controls the audit representation of stored mfa_accounts.mfa_enabled.
	MFAEnabled record.Disclosure
	// RequireMFA controls the audit representation of stored mfa_accounts.require_mfa.
	RequireMFA record.Disclosure
}

// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes AccountChanges) Audit(policy AccountAuditPolicy) (record.Model[Account, model.ID[Account]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Account, model.ID[Account]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Account, model.ID[Account]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Account, model.ID[Account]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Account](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Account, model.ID[Account]]{}, err
	}
	if err = record.Capture(builder, "email", codec.String[string](), changes.fields.Email, policy.Email); err != nil {
		return record.Model[Account, model.ID[Account]]{}, err
	}
	if err = record.Capture(builder, "password", password.Codec(), changes.fields.Password, policy.Password); err != nil {
		return record.Model[Account, model.ID[Account]]{}, err
	}
	if err = record.Capture(builder, "enabled", codec.Bool[bool](), changes.fields.Enabled, policy.Enabled); err != nil {
		return record.Model[Account, model.ID[Account]]{}, err
	}
	if err = record.Capture(builder, "mfa_enabled", codec.Bool[bool](), changes.fields.MFAEnabled, policy.MFAEnabled); err != nil {
		return record.Model[Account, model.ID[Account]]{}, err
	}
	if err = record.Capture(builder, "require_mfa", codec.Bool[bool](), changes.fields.RequireMFA, policy.RequireMFA); err != nil {
		return record.Model[Account, model.ID[Account]]{}, err
	}
	return builder.Build()
}

